import jax.numpy as jnp
import flax.linen as nn
from jax import random
import optax
from typing import Dict, Any, Sequence

# Sourced from storage/veritas/utils.py
class DSConvDilatedBlock(nn.Module):
    d_model: int
    kernel_size: int = 7
    dilation: int = 1
    dropout_rate: float = 0.1 

    @nn.compact
    def __call__(self, x, deterministic=True):
        h = nn.LayerNorm()(x)
        h = nn.Conv(
            features=self.d_model, kernel_size=(self.kernel_size,),
            feature_group_count=self.d_model, padding='SAME',
            kernel_dilation=(self.dilation,), name='dw_conv'
        )(h)
        h = nn.gelu(h)
        h = nn.Conv(features=self.d_model, kernel_size=(1,), name='pw_conv')(h)
        h = nn.Dropout(rate=self.dropout_rate)(h, deterministic=deterministic)
        return x + h

# My implementation of the Task-Specific Heads, now with RegCal
class TaskHead(nn.Module):
    d_output: int
    task_type: str
    dense_dim: int = 128
    dropout_rate: float = 0.1
    reg_head_dropout: float = 0.05
    apply_regcal: bool = True

    @nn.compact
    def __call__(self, x, deterministic=True):
        head_dropout = self.reg_head_dropout if self.task_type == 'regression' else self.dropout_rate

        if self.task_type == 'regression' and self.apply_regcal:
            norm = jnp.linalg.norm(x, ord=2, axis=-1, keepdims=True)
            x = x / (norm + 1e-6)

        z = nn.Dense(self.dense_dim)(x)
        z = nn.gelu(z)
        z = nn.Dropout(rate=head_dropout)(z, deterministic=deterministic)
        logits = nn.Dense(self.d_output)(z)

        if self.task_type == 'regression':
            return logits.squeeze(-1)
        return logits

class SotaReproductionWithRegCal(nn.Module):
    d_output: int
    task_type: str

    d_model: int = 256
    kernel_size: int = 7
    dilations: Sequence[int] = (1, 2, 4, 8, 16)
    dropout_rate: float = 0.1
    motif_detector_kernel_size: int = 5
    motif_detector_features: int = 256

    @nn.compact
    def __call__(self, x, deterministic=True):
        x = nn.Dense(features=self.d_model)(x)

        dsconv_features = x
        for dilation in self.dilations:
            dsconv_features = DSConvDilatedBlock(
                d_model=self.d_model, kernel_size=self.kernel_size,
                dilation=dilation, dropout_rate=self.dropout_rate
            )(dsconv_features, deterministic=deterministic)

        motif_features = nn.Conv(
            features=self.motif_detector_features,
            kernel_size=(self.motif_detector_kernel_size,)
        )(x)
        motif_features = nn.gelu(motif_features)

        main_agg = jnp.concatenate([
            jnp.mean(dsconv_features, axis=1), jnp.max(dsconv_features, axis=1)
        ], axis=-1)
        motif_agg = jnp.max(motif_features, axis=1)

        combined_features = jnp.concatenate([main_agg, motif_agg], axis=-1)
        fused_features = nn.LayerNorm()(combined_features)

        y = TaskHead(d_output=self.d_output, task_type=self.task_type)(fused_features, deterministic=deterministic)
        return y

class NetworkWrapper:
    def __init__(self, **kwargs):
        self.network = SotaReproductionWithRegCal(**kwargs)
    def init(self, rng_key, dummy_input):
        params_key, dropout_key = random.split(rng_key)
        variables = self.network.init({'params': params_key, 'dropout': dropout_key},
                                     dummy_input, deterministic=True)
        return variables['params']
    def apply(self, params, x, deterministic=True, rng_key=None):
        if deterministic:
            return self.network.apply({'params': params}, x, deterministic=True)
        else:
            if rng_key is None: rng_key = random.PRNGKey(0)
            return self.network.apply({'params': params}, x, deterministic=False,
                                    rngs={'dropout': rng_key})

def _define_hyperparameters():
    return {'learning_rate': 0.001}

def create_network(hparams: Dict[str, Any]):
    return NetworkWrapper(d_output=hparams["d_output"], task_type=hparams["task_type"])

def create_optimizer(learning_rate: float = 0.001) -> optax.GradientTransformation:
    # Using the optimized weight decay from Veritas III's paper
    return optax.chain(
        optax.clip_by_global_norm(1.0),
        optax.adamw(learning_rate=learning_rate, weight_decay=0.012)
    )
